<?php
namespace Pterodactyl\Services\Nodexa;
use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Http; use RuntimeException;
class FlaxVpsClient { private object $provider; public function __construct(?object $provider=null){$this->provider=$provider?:DB::table('vps_providers')->where('active',true)->first();if(!$this->provider)throw new RuntimeException('Flax VPS provider er ikke konfigureret.');} private function key():string{return Crypt::decryptString($this->provider->api_key);} public function request(string $action,array $params=[],string $method='POST'):array{$key=$this->key();$url=rtrim($this->provider->endpoint,'/').'/api-endpoint.php';$query=array_merge(['key'=>$key,'action'=>$action],$params);$http=Http::timeout(15)->acceptJson()->withToken($key)->withUserAgent('Nodexa-Flax-VPS/1.0');$response=strtoupper($method)==='GET'?$http->get($url,$query):$http->asForm()->post($url,$query);if(!$response->successful())throw new RuntimeException('Flax API HTTP '.$response->status());$json=$response->json();if(!is_array($json))throw new RuntimeException('Ugyldigt svar fra Flax API.');if(($json['status']??null)==='error')throw new RuntimeException((string)($json['data']??'Flax API fejl'));return $json['data']??$json;} public function servers():array{return $this->request('user_servers',[],'GET');} public function info(string $id):array{return $this->request('info',['server_id'=>$id],'GET');} public function power(string $id,string $action):array{if(!in_array($action,['boot','shutdown','restart','poweroff'],true))throw new RuntimeException('Ugyldig VPS handling.');return $this->request($action,['server_id'=>$id]);} public function os(string $id):array{return $this->request('os_info',['server_id'=>$id],'GET');} public function rebuild(string $id,string $os):array{return $this->request('build',['server_id'=>$id,'operatingSystem'=>$os]);} public function create(string $productId,string $osId):array{return $this->request('create',['productId'=>$productId,'operatingSystem'=>$osId]);}}
